import{_ as e,o as a,c as n,a2 as p}from"./chunks/framework.Bg-Zxr5O.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Date-Extraction.md","filePath":"manual-zh/Date-Extraction.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Date-Extraction.md"};function r(m,t,_,d,s,i){return a(),n("div",null,[...t[0]||(t[0]=[p('<h4 id="_7-7-8-5-检查日期的函数" tabindex="-1">7.7.8.5 检查日期的函数 <a class="header-anchor" href="#_7-7-8-5-检查日期的函数" aria-label="Permalink to &quot;7.7.8.5 检查日期的函数&quot;">​</a></h4><p>这些函数接受 PSPP 日期或时间格式的数值参数，并返回数值结果。以下名称用于参数：</p><p>date</p><p>PSPP 日期格式的数值。</p><p>time</p><p>PSPP 时间格式的数值。</p><p>time-or-date</p><p>PSPP 时间或日期格式的数值。</p><p>Function: __<strong>XDATE.DATE</strong> <em>( time-or-date)</em></p><p>对于时间，得到 time-or-date 所包含的整天数对应的时间。对于日期，得到对应于 time-or-date 当时或之前最近午夜的日期；即给出 time-or-date 所处的日期。</p><p>Function: __<strong>XDATE.HOUR</strong> <em>( time-or-date)</em></p><p>对于时间，得到 time-or-date 所表示的整天数之外还剩余的整小时数。对于日期，得到对应于 time-or-date 的小时（0 到 23 之间的整数）。</p><p>Function: __<strong>XDATE.JDAY</strong> <em>( date)</em></p><p>得到对应于 date 的年中第几天（1 到 366 之间的整数）。</p><p>Function: __<strong>XDATE.MDAY</strong> <em>( date)</em></p><p>得到对应于 date 的月中第几天（1 到 31 之间的整数）。</p><p>Function: __<strong>XDATE.MINUTE</strong> <em>( time-or-date)</em></p><p>得到 time-or-date 中最后一个小时之后的分钟数（0 到 59 之间的整数）。</p><p>Function: __<strong>XDATE.MONTH</strong> <em>( date)</em></p><p>得到对应于 date 的年中第几月（1 到 12 之间的整数）。</p><p>Function: __<strong>XDATE.QUARTER</strong> <em>( date)</em></p><p>得到对应于 date 的年中第几季度（1 到 4 之间的整数）。</p><p>Function: __<strong>XDATE.SECOND</strong> <em>( time-or-date)</em></p><p>得到 time-or-date 中最后一个整分钟之后的整秒数（0 到 59 之间的整数）。</p><p>Function: __<strong>XDATE.TDAY</strong> <em>( date)</em></p><p>得到从 1582 年 10 月 14 日到 date 的整天数。</p><p>Function: __<strong>XDATE.TIME</strong> <em>( date)</em></p><p>得到对应于 date 的时刻的时间值。这是从 date 对应那天的午夜起的秒数。</p><p>Function: __<strong>XDATE.WEEK</strong> <em>( date)</em></p><p>得到对应于 date 的年中第几周（1 到 53 之间的整数）。</p><p>Function: __<strong>XDATE.WKDAY</strong> <em>( date)</em></p><p>得到对应于 date 的星期几（1 到 7 之间的整数），其中 1 代表星期日。</p><p>Function: __<strong>XDATE.YEAR</strong> <em>( date)</em></p><p>返回对应于 date 的年份（1582 或更大的整数）。</p>',34)])])}const E=e(o,[["render",r]]);export{g as __pageData,E as default};
